    exit "$status"
  fi
  [ -n "$expected" ] || return 0
  actual=$(printf "%s\n" "$output" | sed -n "$pattern" | sed -n "1p")
  case "$mode:$actual" in
    "exact:$expected"|"prefix:$expected"|"prefix:$expected".*) return 0 ;;
    *)
      printf "BLOCKED: %s requires %s; found %s\n" "$label" "$expected" "${actual:-unrecognized version}" >&2
      exit 69 ;;
  esac
}

